from . import interface_tools
from .name_logger import log_name
from . import robot_variables


class ta5g_interface_tools(object):
    @staticmethod
    def add_remote_host_suffix(alias, remote_host):
        """
        :param alias: Name of execution context
        :param remote_host: ip address of eNB host PC. None means local host
        :return: extended alias for remote host suffix
        """
        return alias + remote_host if remote_host not in (None, "127.0.0.1") else alias

    @staticmethod
    def create_remote_host_list(remote_hosts):
        """
        :param remote_hosts: ip address or list of ip addresses of eNB host PC
        :return: list of remote_host/s
        """
        if remote_hosts is None:
            return [None]
        else:
            return interface_tools.force_list(remote_hosts)

    @staticmethod
    def force_list(parameter):
        """
        Converts non-list parameter to a single-element list
        """
        return interface_tools.force_list(parameter)

    @staticmethod
    def join_string_with_timestamp_suffix(string):
        """
        Joins string given as an argument with timestamp
        :param string: string
        :return: string - underscore - timestamp as a string
        """
        return interface_tools.join_string_with_timestamp_suffix(str(string))

    @staticmethod
    def convert_parameter_to_integer(param):
        """
        Extracts positive or negative integer from a string.
        Useful in case of SIB parameters conversion.
        :param param: String
        :return: extracted positive or negative integer from given param
        """
        return interface_tools.convert_parameter_to_integer(param)

    @staticmethod
    def get_robot_test_name():
        """
        Returns the value of Robot Framework variable ${TEST_NAME}
        """
        return robot_variables.get_robot_test_name()

    @staticmethod
    def get_robot_suite_name():
        """
        Returns the value of Robot Framework variable ${SUITE_NAME}
        """
        return robot_variables.get_robot_suite_name()

    @staticmethod
    def get_robot_suite_source():
        """
        Returns the value of Robot Framework variable ${SUITE_SOURCE}
        """
        return robot_variables.get_robot_suite_source()

    @staticmethod
    def get_robot_output_dir():
        """
        Returns the value of Robot Framework variable ${OUTPUT_DIR}
        """
        return robot_variables.get_robot_output_dir()

    @staticmethod
    def get_robot_exec_dir():
        """
        Returns the value of Robot Framework variable ${EXECDIR}
        """
        return robot_variables.get_robot_exec_dir()

    @staticmethod
    def get_robot_temp_dir():
        """
        Returns the value of Robot Framework variable ${TEMPDIR}
        """
        return robot_variables.get_robot_temp_dir()

    @staticmethod
    def get_robot_cur_dir():
        """
        Returns the value of Robot Framework variable ${CURDIR}
        """
        return robot_variables.get_robot_cur_dir()

    @staticmethod
    def is_robot_context_active():
        try:
            robot_variables.get_robot_output_dir()
            return True
        except Exception:
            return False
